      if (Math.hypot(dx, dy) < m.radius + ship.radius) {
        score += 10;
        minerals.splice(i, 1);
        continue;
      }
      // remove if off‑screen
      if (m.y - m.radius > canvas.height) minerals.splice(i, 1);
    }
    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.speedX;
      a.y += a.speedY;
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      if (Math.hypot(dx, dy) < a.radius + ship.radius) {
        ship.shield -= 20;
